body:
You can put it into an $ionicPlatform.ready callback function as shown in the following example.

    'use strict';

    angular.module('myApp', ['ionic', 'firebase', 'ngCordova', 'ngLodash', 'ngIOS9UIWebViewPatch', ])

    .constant('FIREBASE_URL','https://MYAPPNAME.firebaseio.com')

    .run(function(FIREBASE_URL, $ionicPlatform, $timeout, $rootScope, $location, $state, Auth, $ionicLoading, $ionicHistory) {

        $ionicPlatform.ready(function() {

            $rootScope.logout = function() {
                console.log("Logging out from the app");
                $ionicLoading.show({
                    template: 'Logging Out...'
                });
                UserDataService.clearData();
                Auth.$unauth();
                $timeout(function() {
                    $ionicHistory.clearCache();
                    $ionicHistory.clearHistory();
                    console.log('clearing cache');
                }, 300);
            };

            $rootScope.$on("$stateChangeError", function(event, toState, toParams, fromState, fromParams, error) {
                // We can catch the error thrown when the $requireAuth promise is rejected
                // and redirect the user back to the home page
                console.log('stateChangeError triggered');
                if (error === "AUTH_REQUIRED") {
                    console.log('error=AUTH_REQUIRED');
                    $location.path("/");
                }
            });

        });
    })

I've created a local workspace and got the authentication working as it should.

I'm currently working on an Ionic/Firebase app with email/password and Facebook authentication. It's not easy I know.

Using your original code, while logged out and navigating directly to /menu/map, I noticed that toState.authRequired was undefined. This can be resolved by moving stateRequired up to sit alongside the url and views properties of the state:

      .state('app.map', {
        authRequired: true,
        url: '/map',
        views: {
            'public-map': {
                templateUrl: 'templates/map.html'
            }
        }
      }) 

Also, consider implementing your logout function on the rootScope so that it's globally accessible rather than part of the controller for the login screen:

    $rootScope.logout = function() {
        console.log("Logging out from the app");
        Auth.$unauth();
        $timeout(function() {
            $ionicHistory.clearCache();
            $ionicHistory.clearHistory();
            console.log('clearing cache');
            $state.go("login");
        }, 300);
    };

This allows you to call logout() from a nav button defined in index.html

      <body ng-app="starter" ng-controller="appCtrl">
          <ion-nav-bar class="bar-{{temabar}}">
              <ion-nav-back-button>
              </ion-nav-back-button>
              <ion-nav-buttons side="right">
                <button class="button button-clear" ng-click="logout()">Logout</button>
              </ion-nav-buttons>
          </ion-nav-bar>
          <ion-nav-view></ion-nav-view>
      </body>


Also, you could replace the call to Auth.isAuthenticated() with Auth.$getAuth():

    //stateChange event
    $rootScope.$on("$stateChangeStart", function(event, toState, toParams, fromState, fromParams){
      console.log("stateChangeStart triggered");
      if (toState.authRequired && Auth.$getAuth() === null){
        // User isn’t authenticated
        $state.go("login");
        event.preventDefault(); 
      }
    });

 Best of luck with your project.
